/// <summary>
/// Demonstrates different X++ exception types based on user selection.
/// </summary>
class METDashboardException extends RunBaseBatch
{
    DialogField                dialogExceptionType;
    METDashboardExceptionType  exceptionType;

    #define.CurrentVersion(1)
    #localmacro.CurrentList
        exceptionType
    #endmacro
}

Method.Source:
public Object dialog()
{
    Dialog dialog = super();

    dialog.caption("@SYS:ExceptionDemo");
    dialogExceptionType = dialog.addFieldValue(enumStr(METDashboardExceptionType), exceptionType, "Exception type", "Select the type of exception to generate");

    return dialog;
}

public boolean getFromDialog()
{
    exceptionType = dialogExceptionType.value();
    return super();
}

public void run()
{
    switch (exceptionType)
    {
        case METDashboardExceptionType::Error:
            this.generateErrorException();
            break;

        case METDashboardExceptionType::RecordNotSelected:
            this.generateRecordNotSelectedException();
            break;

        case METDashboardExceptionType::UpdateNotInTTS:
            this.generateUpdateNotInTTSException();
            break;

        case METDashboardExceptionType::UpdateByDiffUser:
            this.generateUpdateByDifferentUserException();
            break;

        case METDashboardExceptionType::Deadlock:
            this.generateDeadlockException();
            break;

        default:
            info("No exception type selected.");
            break;
    }
}

private void generateErrorException()
{
    throw error("VALIDATE EXCEPTION: ERROR - This is a custom error exception");
}

private void generateRecordNotSelectedException()
{
    CustGroup custGroup;

    // Attempting to update without selecting a record first
    // This will cause "Record not selected" exception
    custGroup.Name = "Test";
    custGroup.update();
}

private void generateUpdateNotInTTSException()
{
    CustGroup custGroup;

    // Select a record but update outside of transaction scope
    select firstonly forupdate custGroup;

    if (custGroup)
    {
        // This will cause "Update not in TTS" exception
        // because we are not inside a ttsbegin/ttscommit block
        custGroup.Name = custGroup.Name;
        custGroup.update();
    }
    else
    {
        info("No CustGroup record found to update.");
    }
}

private void generateUpdateByDifferentUserException()
{
    CustGroup custGroup;
    CustGroup custGroupCopy;

    ttsbegin;

    // Select the same record twice with forupdate
    select firstonly forupdate custGroup;

    if (custGroup)
    {
        // Simulate another user updating the record by changing RecVersion
        custGroupCopy.data(custGroup);

        // First update succeeds
        custGroup.Name = custGroup.Name;
        custGroup.update();

        // Now try to update with the old RecVersion (simulating different user)
        // This causes "Update conflict" / "Update by different user" exception
        custGroupCopy.update();
    }
    else
    {
        info("No CustGroup record found to update.");
    }

    ttscommit;
}

private void generateDeadlockException()
{
    CustGroup   custGroup;
    CustTable   custTable;

    info("To generate a deadlock, you need to run two sessions simultaneously:");
    info("Session 1: Lock CustGroup first, then try to lock CustTable");
    info("Session 2: Lock CustTable first, then try to lock CustGroup");
    info("");
    info("Starting Session 1 behavior - locking CustGroup with pessimistic lock...");
    info("Open another session and run this with Deadlock option to create the deadlock condition.");

    ttsbegin;

    // Pessimistic lock on CustGroup
    select firstonly pessimisticlock custGroup;

    if (custGroup)
    {
        info(strFmt("Locked CustGroup: %1. Waiting 30 seconds for second session...", custGroup.CustGroup));

        // Wait to allow second session to lock CustTable
        sleep(30000);

        // Now try to lock CustTable - this will deadlock if second session has it locked
        select firstonly pessimisticlock custTable;

        if (custTable)
        {
            info(strFmt("Also locked CustTable: %1", custTable.AccountNum));
        }
    }
    else
    {
        info("No CustGroup record found.");
    }

    ttscommit;
}

public boolean unpack(container _packedClass)
{
    int version = RunBase::getVersion(_packedClass);

    switch (version)
    {
        case #CurrentVersion:
            [version, #CurrentList] = _packedClass;
            break;
        default:
            return false;
    }

    return true;
}

public static ClassDescription description()
{
    return "Dashboard Exception Demo";
}

public static void main(Args _args)
{
    METDashboardException demo = new METDashboardException();

    if (demo.prompt())
    {
        demo.run();
    }
}

public static METDashboardException construct()
{
    return new METDashboardException();
}
